def readcsv(p):return list(csv.DictReader((ROOT/p).open()))
def js(p,o):
 (ROOT/p).parent.mkdir(parents=True,exist_ok=True)
 (ROOT/p).write_text(json.dumps(o,ensure_ascii=False,indent=2,allow_nan=False)+'\n')
def csvout(p,rows,fields=None):
 (ROOT/p).parent.mkdir(parents=True,exist_ok=True)
 with (ROOT/p).open('w',newline='') as f:
  w=csv.DictWriter(f,fieldnames=fields or list(rows[0]));w.writeheader();w.writerows(rows)
def sha(p):return hashlib.sha256((ROOT/p).read_bytes()).hexdigest()
def csha(o):return hashlib.sha256(json.dumps(o,ensure_ascii=False,sort_keys=True,separators=(',',':')).encode()).hexdigest()
def ref(r):return {'input_id':r['_source_input_id'],'source_data_row':int(r['_source_data_row']),'row_sha256':r['_source_row_sha256'],'source_blob_sha256':r['_source_blob_sha256'],'commit':r['_source_commit'],'product_id':r.get('product_id'),'source_url':r.get('source_url',r.get('source','UNKNOWN'))}

COORD={r['iata']:(float(r['latitude_deg']),float(r['longitude_deg'])) for r in readcsv('inputs/AUTHOR_catchments.csv')}
TZ={'ZIA':3,'DME':3,'VKO':3,'SVO':3,'KGD':2,'KUF':4,'GSV':4,'OMS':6,'KRO':5,'CEK':5,'PEE':5,'IJK':4,'REN':5,'TJM':5,'NOJ':5,'MQF':5,'SGC':5,'HMA':5,'ARH':3,'MRV':3,'VOG':3,'MCX':3,'AER':3,'GOJ':3}
def gc(a,b):
 la,lo=map(math.radians,COORD[a]);lb,lob=map(math.radians,COORD[b]);h=math.sin((lb-la)/2)**2+math.cos(la)*math.cos(lb)*math.sin((lob-lo)/2)**2
 return 2*6371*math.asin(min(1,math.sqrt(h)))
def block(a,b,k=1.2):
 if 'KGD' in {a,b}:
  other=next(x for x in [a,b] if x!='KGD')
  return {'DME':170,'ZIA':170,'GOJ':190,'KUF':225}.get(other)
 return math.ceil((30+60*k*gc(a,b)/750)/5)*5
def pairkey(a,b):return ':'.join(sorted((a,b)))

